package eval

func idempotencyKeysSuite() Suite {
	base := eventProjectionsSuite()
	firstEvent := map[string]any{"event_id": "idem-1", "value": "once", "sequence": 1, "idempotency_key": "key-080-a"}
	secondEvent := map[string]any{"event_id": "idem-2", "value": "twice", "sequence": 2, "idempotency_key": "key-080-b"}
	return Suite{ID: "080-idempotency-keys", Name: "Campaign Play 080: Idempotency Keys", Tests: append(base.Tests,
		playTest("play-idempotency-create-campaign", "DM creates a fresh campaign for idempotency events", "POST", "/v1/play/campaigns", map[string]any{"id": "play-080", "name": "Idempotency Campaign", "max_players": 2}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"id": "play-080", "name": "Idempotency Campaign", "owner": "dm", "status": "lobby", "max_players": 2}),
		playTest("play-idempotency-join-player-a", "Player A joins the idempotency campaign", "POST", "/v1/play/campaigns/play-080/members", map[string]any{"character_id": "play-080-char-a", "name": "Aria", "class": "rogue"}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"username": "player-a", "character_id": "play-080-char-a", "name": "Aria", "class": "rogue"}),
		playTest("play-idempotency-unauthenticated", "Unauthenticated idempotent event append is rejected", "POST", "/v1/play/campaigns/play-080/idempotent-events", map[string]any{"event_id": "idem-unauth", "value": "bad"}, map[string]string{"Idempotency-Key": "key-080-unauth"}, 401, nil),
		playTest("play-idempotency-missing-key", "Idempotency-Key is mandatory", "POST", "/v1/play/campaigns/play-080/idempotent-events", map[string]any{"event_id": "idem-missing-key", "value": "bad"}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTest("play-idempotency-empty-key", "Idempotency-Key must be nonempty", "POST", "/v1/play/campaigns/play-080/idempotent-events", map[string]any{"event_id": "idem-empty-key", "value": "bad"}, map[string]string{"Authorization": playerAAuth, "Idempotency-Key": "   "}, 400, nil),
		playTest("play-idempotency-empty-event-id", "Idempotent event_id must be nonempty", "POST", "/v1/play/campaigns/play-080/idempotent-events", map[string]any{"event_id": "", "value": "bad"}, map[string]string{"Authorization": playerAAuth, "Idempotency-Key": "key-080-empty-event"}, 400, nil),
		playTest("play-idempotency-empty-value", "Idempotent event value must be nonempty", "POST", "/v1/play/campaigns/play-080/idempotent-events", map[string]any{"event_id": "idem-empty-value", "value": ""}, map[string]string{"Authorization": playerAAuth, "Idempotency-Key": "key-080-empty-value"}, 400, nil),
		playTestExactJSON("play-idempotency-create-first", "First valid idempotent event creates sequence one", "POST", "/v1/play/campaigns/play-080/idempotent-events", map[string]any{"event_id": "idem-1", "value": "once"}, map[string]string{"Authorization": playerAAuth, "Idempotency-Key": "key-080-a"}, 201, firstEvent),
		playTestExactJSON("play-idempotency-replay-first", "Same key and payload replays identical event without another effect", "POST", "/v1/play/campaigns/play-080/idempotent-events", map[string]any{"event_id": "idem-1", "value": "once"}, map[string]string{"Authorization": playerAAuth, "Idempotency-Key": "key-080-a"}, 200, firstEvent),
		playTest("play-idempotency-same-key-different-payload", "Same key with different payload conflicts", "POST", "/v1/play/campaigns/play-080/idempotent-events", map[string]any{"event_id": "idem-1", "value": "changed"}, map[string]string{"Authorization": playerAAuth, "Idempotency-Key": "key-080-a"}, 409, nil),
		playTest("play-idempotency-duplicate-event-different-key", "Duplicate event ID with a different key conflicts", "POST", "/v1/play/campaigns/play-080/idempotent-events", map[string]any{"event_id": "idem-1", "value": "once"}, map[string]string{"Authorization": playerAAuth, "Idempotency-Key": "key-080-duplicate-event"}, 409, nil),
		playTestExactJSON("play-idempotency-create-second", "Different key and new event creates next sequence", "POST", "/v1/play/campaigns/play-080/idempotent-events", map[string]any{"event_id": "idem-2", "value": "twice"}, map[string]string{"Authorization": dmAuth, "Idempotency-Key": "key-080-b"}, 201, secondEvent),
		playTestExactJSON("play-idempotency-read-player", "Campaign member reads exact ordered idempotent events with one effect per key", "GET", "/v1/play/campaigns/play-080/idempotent-events", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"events": []any{firstEvent, secondEvent}}),
		playTestExactJSON("play-idempotency-read-dm", "DM reads the same exact ordered idempotent events", "GET", "/v1/play/campaigns/play-080/idempotent-events", nil, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"events": []any{firstEvent, secondEvent}}),
		playTest("play-idempotency-read-nonmember-forbidden", "Non-member cannot read idempotent events", "GET", "/v1/play/campaigns/play-080/idempotent-events", nil, map[string]string{"Authorization": "Bearer session-stranger"}, 403, nil),
	)}
}
